     */
    case rename(
        /**
         * The item.
         */item: LibrarianItem, 
        /**
         * The new name.
         */name: String
    )
    /**
     * Create the collection `path`.
     */
    case collection(
        /**
         * Its path.
         */path: String, 
        /**
         * What belongs in it.
         */description: String
    )





}

