        /**
         * The item before's title.
         */from: String, 
        /**
         * How near: 1 is the same direction.
         */score: Float
    )
    /**
     * It's in the same collection as the item before.
     */
    case neighbour(
        /**
         * The collection.
         */collection: String
    )
    /**
     * A jump to a collection not opened in a while.
     */
    case jump(
        /**
         * The collection.
         */collection: String, 
        /**
         * When it was last seen, as `YYYY-MM-DD`, if ever.
         */lastSeen: String?
    )





}

